import { integer } from '../';

describe('integer mask', () => {
  it('should not mask null', () => {
    expect(integer(null)).toEqual(null);
  });

  it('should mask letters', () => {
    expect(integer('9h.s3')).toEqual('93');
  });

  it('should not mask numbers', () => {
    expect(integer('53.27')).toEqual('5327');
  });

  it('should work with large numbers', () => {
    expect(integer(' 999, 995, 327.00 ')).toEqual('99999532700');
  });

  it('should allow negative', () => {
    expect(integer('-53.27')).toEqual('-5327');
  });
});
